package com.ruoyi.hexu;
import com.ruoyi.common.annotation.Anonymous;
import org.springframework.web.bind.annotation.*;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.util.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.math.BigDecimal;
import static com.ruoyi.hexu.HexuStore.*;
@Anonymous @RestController @RequestMapping({"/hexu/app/management/reports","/hexu/admin/reports"})
public class HexuReportController {
 private final HexuIdentity auth;private final HexuStore db;private final HexuWorkflowService workflow;
 public HexuReportController(HexuIdentity a,HexuStore d,HexuWorkflowService w){auth=a;db=d;workflow=w;}
 private Actor actor(HttpServletRequest r){return r.getRequestURI().contains("/hexu/admin/")?auth.admin():auth.member(r);}
 @GetMapping public Object list(HttpServletRequest r,@RequestParam long shopId){return HexuAppController.ok(new HexuReports(db).list(actor(r),shopId));}
 @GetMapping("/{id}") public Object get(HttpServletRequest r,@PathVariable String id,@RequestParam(defaultValue="SHOP")String dimension,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="100")int size){return HexuAppController.ok(new HexuReports(db).view(actor(r),id,dimension,page,size));}
 @GetMapping("/{id}/inventory") public Object inventory(HttpServletRequest r,@PathVariable String id,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="100")int size){return HexuAppController.ok(new HexuReports(db).inventory(actor(r),id,page,size));}
 static String csv(Object value){String s=value==null?"":String.valueOf(value);if(!s.stripLeading().isEmpty()&&"=+@-".indexOf(s.stripLeading().charAt(0))>=0||s.startsWith("\t")||s.startsWith("\r"))s="'"+s;return "\""+s.replace("\"","\"\"")+"\"";}
 static String[][] columns(String d){if("INVENTORY".equals(d))return new String[][]{{"shop_id","商城编号"},{"sku_id","商品编号"},{"sku_name","商品名称"},{"available","可售库存"},{"locked","锁定库存"},{"defective","不良品库存"},{"in_transit","在途数量"},{"warning_qty","预警值"},{"average_stock","日均可用及锁定库存"},{"quantity","筛选后的净销量"},{"turnoverDays","参考周转天数"},{"stockStatus","库存状态"}};List<String[]>cols=new ArrayList<>();switch(d){case "COUNTY":cols.add(new String[]{"county","县域"});break;case "RANK":cols.add(new String[]{"rank_no","历史职级"});break;case "DAY":case "MONTH":cols.add(new String[]{"day","日期"});break;default:cols.add(new String[]{"shop_id","商城编号"});cols.add(new String[]{"shop_name","商城名称"});}if("SKU".equals(d)){cols.add(new String[]{"sku_id","商品编号"});cols.add(new String[]{"sku_name","商品名称"});}if("AGENT".equals(d)){cols.add(new String[]{"agent_id","历史代理编号"});cols.add(new String[]{"agent_name","代理姓名"});cols.add(new String[]{"rank_no","历史职级"});}if("CUSTOMER".equals(d)||"ORDER".equals(d)){cols.add(new String[]{"buyer_id","客户编号"});cols.add(new String[]{"buyer_name","客户姓名"});}if("ORDER".equals(d)){cols.add(new String[]{"order_id","订单号"});cols.add(new String[]{"order_status","快照订单状态"});}Collections.addAll(cols,new String[]{"orders","有效订单"},new String[]{"quantity","净销量"},new String[]{"gross_sales","商品实付（元）","money"},new String[]{"refunds","商品退款（元）","money"},new String[]{"net_sales","净销售额（元）","money"},new String[]{"distribution_cost","历史职级成本（元）","money"},new String[]{"distributionMargin","已知成本价差毛利（元）","money"},new String[]{"unknown_cost_sales","未记录成本销售额（元）","money"},new String[]{"earnings","扣除冲正后净收益（元）","money"});return cols.toArray(new String[0][]);}
 @GetMapping("/{id}/export") public void export(HttpServletRequest request,HttpServletResponse response,@PathVariable String id,@RequestParam(defaultValue="SHOP")String dimension)throws IOException{Actor a=actor(request);workflow.auditReportExport(a,id,dimension);String[][]cols=columns(dimension);response.setContentType("text/csv;charset=UTF-8");response.setHeader("Cache-Control","no-store");response.setHeader("Content-Disposition","attachment; filename=report-"+dimension+".csv");BufferedWriter w=new BufferedWriter(new OutputStreamWriter(response.getOutputStream(),StandardCharsets.UTF_8));w.write('\ufeff');for(int c=0;c<cols.length;c++){if(c>0)w.write(',');w.write(csv(cols[c][1]));}w.write("\r\n");HexuReports reports=new HexuReports(db);for(int page=1;;page++){List<Map<String,Object>>rows="INVENTORY".equals(dimension)?reports.inventory(a,id,page,1000):reports.rows(a,id,dimension,page,1000);for(Map<String,Object>r:rows){for(int c=0;c<cols.length;c++){if(c>0)w.write(',');Object value=r.get(cols[c][0]);if(cols[c].length>2)value=BigDecimal.valueOf(number(r,cols[c][0]),2).toPlainString();w.write(csv(value));}w.write("\r\n");}w.flush();if(rows.size()<1000)break;}}
}
